import Image from "next/image";

/** Horizontal lockup (CW mark + "CodeWaveTech"), generated by scripts/brand_assets.py. */
const RATIO = 952 / 136;

/**
 * `surface="auto"` follows the theme (navy wordmark on light, light wordmark on
 * dark). `surface="dark"` always uses the light wordmark (e.g. the footer).
 */
export function BrandLogo({
  height = 34,
  surface = "auto",
  priority = false,
}: {
  height?: number;
  surface?: "auto" | "dark";
  priority?: boolean;
}) {
  const width = Math.round(height * RATIO);
  const alt = "CodeWaveTech home";
  if (surface === "dark") {
    return <Image src="/brand/logo-horizontal-light.png" alt={alt} width={width} height={height} />;
  }
  return (
    <>
      <Image
        className="logo-on-light"
        src="/brand/logo-horizontal.png"
        alt={alt}
        width={width}
        height={height}
        priority={priority}
      />
      <Image
        className="logo-on-dark"
        src="/brand/logo-horizontal-light.png"
        alt={alt}
        width={width}
        height={height}
      />
    </>
  );
}
